export type SearchPeopleRequest = {
  /**
   * Search keywords. Matches against name, headline, company, skills, and bio. Optional: you can search by filters alone (e.g. all 2nd-degree connections in Paris). Supports LinkedIn Boolean syntax, use double quotes for exact phrases (e.g. "product manager"), AND to require both terms, OR for alternatives (e.g. CEO OR founder OR CTO), NOT to exclude (e.g. manager NOT assistant), and parentheses to group (e.g. (CEO OR CTO) AND SaaS). Operators must be UPPERCASE.
   */
  keywords?: string | undefined;
  /**
   * A LinkedIn search URL. The category and every filter the vertical can actually apply are read from it; a facet it carries that this search cannot apply is reported back as a URL_FACET warning rather than applied, so a result set carrying those is WIDER than the URL asked for. Explicit params override anything read from the URL.
   */
  url?: string | undefined;
  /**
   * Spend up to this many searches on one ask, cutting it along independent angles so the result reaches people a single search cannot. One search returns about ten people; the angles do not overlap much, so the total grows close to linearly with what you spend. Leave it out to run exactly one search.
   */
  maxSearches?: number | undefined;
  /**
   * Filter by connection degree. 'F' = 1st degree (your direct connections), 'S' = 2nd degree (connections of connections), 'O' = 3rd+ degree and out of network. Accepts multiple values, e.g. ['F','S'] for 1st and 2nd degree.
   */
  connectionDegree?: Array<SearchPeopleConnectionDegree> | undefined;
  /**
   * Filter by first name. Exact match (case-insensitive).
   */
  firstName?: string | undefined;
  /**
   * Filter by last name. Exact match (case-insensitive).
   */
  lastName?: string | undefined;
  /**
   * Filter by current job title. Matches against the person's current position title. Supports LinkedIn Boolean OR: 'CEO OR CTO OR Founder'. Pipe separators are auto-converted, 'CEO|CTO|Founder' becomes 'CEO OR CTO OR Founder'. Use double quotes for exact multi-word titles, '"Head of Marketing" OR "VP Sales"'.
   */
  title?: string | undefined;
  /**
   * Find connections of a specific person. Pass the person's LinkedIn profile URN (e.g. 'urn:li:fsd_profile:ACoAAB1234...'). Returns people who are connected to this person.
   */
  connectionOf?: string | undefined;
  /**
   * Filter by LinkedIn profile language. Array of ISO 639-1 codes (e.g. ['en','fr']); the server resolves any code.
   */
  profileLanguage?: Array<string> | undefined;
  /**
   * Filter by school/university. Pass human names (e.g. ['Harvard','Stanford']): server resolves to LinkedIn IDs via typeahead. Numeric IDs pass through if you already have them.
   */
  school?: Array<string> | undefined;
  /**
   * Filter by geographic location. Pass human names (e.g. ['Paris','France']): server resolves to LinkedIn geo IDs via typeahead. Numeric IDs pass through if you already have them.
   */
  location?: Array<string> | undefined;
  /**
   * Filter by industry. Pass human names (e.g. ['Software Development','Marketing']): server resolves to LinkedIn industry IDs via typeahead. Numeric IDs pass through if you already have them.
   */
  industry?: Array<string> | undefined;
  /**
   * Filter by current employer. Pass company names (e.g. ['Stripe','Datadog']): server resolves to LinkedIn company IDs via typeahead. Numeric IDs pass through if you already have them.
   */
  currentCompany?: Array<string> | undefined;
  /**
   * Filter by past employer. Pass company names: server resolves to LinkedIn company IDs via typeahead. Numeric IDs pass through if you already have them. Finds people who previously worked at these companies.
   */
  pastCompany?: Array<string> | undefined;
  /**
   * Find people who follow a specific creator/thought-leader. Array of LinkedIn profile URNs (e.g. 'urn:li:fsd_profile:ACoAAB...'). A warm-discovery vector: the audience of an influential voice in your space. Get URNs from a prior search_people result.
   */
  followersOf?: Array<string> | undefined;
  /**
   * When true, only return people who marked themselves open to volunteering.
   */
  openToVolunteering?: boolean | undefined;
  /**
   * Filter by LinkedIn Service-Marketplace category: for finding freelancers/consultants. Pass category NAMES (e.g. ['Digital Marketing','Web Development','Management Consulting']), resolved to IDs server-side.
   */
  serviceCategories?: Array<string> | undefined;
  /**
   * Only people whose identity LinkedIn has verified. Reaches a different set rather than a smaller one: measured, it kept about half the unfiltered results and replaced the rest.
   */
  verifiedOnly?: boolean | undefined;
  /**
   * School as free text, matched on the name rather than an id. Use this when you know what the school is called but not its LinkedIn id; use `school` when you have the id.
   */
  schoolFreetext?: string | undefined;
  /**
   * Location IDs of the company HEADQUARTERS, which is a different question from where the person is. A rep in Paris at a Berlin-headquartered firm matches one and not the other. Resolve ids via /search/linkedin/parameters.
   */
  companyHQ?: Array<string> | undefined;
  /**
   * Company size on the PEOPLE search (employer headcount). Pass a human employee range and it is converted for you: A=1, B=2-10, C=11-50, D=51-200, E=201-500, F=501-1000, G=1001-5000, H=5001-10000, I=10001+.
   */
  companySize?: Array<string> | undefined;
  /**
   * Pagination offset into the accumulated result list (default 0). Results come about ten per page; use multiples of ten to skip whole pages.
   */
  start?: number | undefined;
  /**
   * How many people to return in total (default 10, max 50).
   */
  count?: number | undefined;
};

